                "Idempotency-Key"?: components["parameters"]["OptionalIdempotencyKey"];
                /** @description login/refresh/logout은 server exact allowlist와 일치해야 하며 absent/null도 mutation 전에 거부한다. */
                Origin: components["parameters"]["OriginHeader"];
                /** @description auth cookie가 모두 없는 logout retry에서만 생략 가능; 하나라도 있으면 선택 profile의 signed cookie와 함께 필수다. */
